        "icon": "https://cdn.jsdelivr.net/npm/bootstrap-icons@1.11.3/icons/tree.svg",
        "actionLabel": "View Arashiyama Map",
        "actionUrl": "https://www.japan-guide.com/e/e3912.html"
      },
      {
        "day": "Day 2: Higashiyama Traditions & Tea",
        "morningActivity": "Visit Kiyomizu-dera Temple, a UNESCO World Heritage site with panoramic views of Kyoto.",
        "afternoonActivity": "Wander through the historic Gion district, known for its traditional wooden machiya houses and geisha culture.",
        "eveningActivity": "Participate in a traditional tea ceremony experience.",
        "image": "https://upload.wikimedia.org/wikipedia/commons/thumb/e/e7/Kiyomizu-dera_Main_Hall_in_Kyoto%2C_Japan.jpg/1280px-Kiyomizu-dera_Main_Hall_in_Kyoto%2C_Japan.jpg",
        "imageAlt": "Kiyomizu-dera Temple",
        "icon": "https://cdn.jsdelivr.net/npm/bootstrap-icons@1.11.3/icons/cup-hot.svg",
        "actionLabel": "Explore Gion",
        "actionUrl": "https://www.japan-guide.com/e/e3902.html"
      },
      {
        "day": "Day 3: Imperial Grandeur & Modern Art",
        "morningActivity": "Tour the Kyoto Imperial Palace and its serene gardens.",
        "afternoonActivity": "Discover modern art at the Kyoto National Museum of Modern Art.",
        "eveningActivity": "Enjoy a kaiseki dinner, a traditional multi-course Japanese dinner.",
        "image": "https://upload.wikimedia.org/wikipedia/commons/thumb/e/e3/Kyoto_Imperial_Palace_Shishin-den.jpg/1280px-Kyoto_Imperial_Palace_Shishin-den.jpg",
        "imageAlt": "Kyoto Imperial Palace",
        "icon": "https://cdn.jsdelivr.net/npm/bootstrap-icons@1.11.3/icons/building.svg",
        "actionLabel": "Visit Imperial Palace",
